// Verify HMAC-SHA256 of RAW body (ADR-0003).
// Requires Webhook option rawBody=true. Secret: env N8N_WEBHOOK_SECRET (same as Management).
const crypto = require('crypto');

const secret = (typeof process !== 'undefined' && process.env && process.env.N8N_WEBHOOK_SECRET) || '';
if (!secret || !String(secret).trim()) {
  throw new Error('N8N_WEBHOOK_SECRET ausente — fail closed');
}

const item = $input.first();
const headers = item.json.headers || {};
const provided = String(
  headers['x-avs-signature'] || headers['X-AVS-Signature'] || ''
).trim();
if (!provided) {
  throw new Error('X-AVS-Signature ausente');
}

let rawBuf;
if (item.binary && item.binary.data) {
  rawBuf = await this.helpers.getBinaryDataBuffer(0, 'data');
} else if (typeof item.json.body === 'string') {
  rawBuf = Buffer.from(item.json.body, 'utf8');
} else if (item.json.body && typeof item.json.body === 'object') {
  // Fallback frágil — preferir rawBody; só para smoke local
  rawBuf = Buffer.from(JSON.stringify(item.json.body), 'utf8');
} else {
  throw new Error('Raw body indisponível — habilite rawBody no Webhook');
}

const expected = crypto.createHmac('sha256', String(secret).trim()).update(rawBuf).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected, 'utf8'), Buffer.from(provided, 'utf8'))) {
  throw new Error('Assinatura HMAC inválida');
}

const envelope = JSON.parse(rawBuf.toString('utf8'));
return [{ json: envelope }];

// dry_run: sem TiFlux/VHSYS — callback ok imediato
const e = $input.first().json;
return [{
  json: {
    event: e.event,
    resource_type: e.resource_type,
    resource_id: e.resource_id,
    status: 'ok',
    outbox_id: e.outbox_id,
    external: {
      tiflux_ticket_number: (e.payload && e.payload.quote && e.payload.quote.tiflux_ticket_number) || null,
      vhsys_os_id: (e.payload && e.payload.quote && e.payload.quote.vhsys_os_id) || null
    },
    error_message: null,
    dry_run: true,
    _callback_url: e.callback_url
  }
}];

